-- 049 — Reescrita do último lote de artigos para o público 50+ (lote 4)
-- Hábitos, cansaço e energia, memória e foco, saúde mental e semana saudável.

update public.articles set
  title = 'Como criar hábitos saudáveis que duram, em qualquer idade',
  excerpt = 'Por que as boas intenções não viram rotina e 4 técnicas simples, com base na ciência do comportamento, para mudar de vez.',
  read_time = '4 min',
  seo_title = 'Como criar hábitos saudáveis que duram, em qualquer idade',
  seo_description = 'Como criar hábitos saudáveis que duram: começar pequeno, ligar à rotina, facilitar o ambiente e registrar o progresso, com exemplos para 50+.',
  content = $c$[{"type": "image", "url": "https://images.unsplash.com/photo-1554331292-735256644d5f?auto=format&fit=crop&w=1600&q=80", "alt": "Foto ilustrativa: Como criar hábitos saudáveis que duram, em qualquer idade (Unsplash)"}, {"type": "paragraph", "text": "Quase todo mundo sabe o que faz bem: caminhar, comer mais verduras, dormir melhor, beber água. A dificuldade está em transformar a intenção em rotina. A boa notícia é que existem técnicas simples, estudadas pela ciência do comportamento, que aumentam muito as chances de sucesso, em qualquer idade."}, {"type": "heading", "level": 2, "text": "Quanto tempo leva para criar um hábito"}, {"type": "paragraph", "text": "Um estudo conhecido acompanhou pessoas criando hábitos simples, como beber água no almoço ou caminhar depois do jantar. Em média, levou cerca de 2 meses para o hábito ficar automático, com grande variação entre as pessoas. E falhar um dia de vez em quando não atrapalhou o resultado. O que importa é voltar."}, {"type": "heading", "level": 2, "text": "Técnica 1: comece pequeno demais"}, {"type": "paragraph", "text": "Metas grandes dependem de motivação, e a motivação oscila. Comece com uma versão tão pequena que pareça fácil demais:"}, {"type": "list", "items": ["Em vez de caminhar 1 hora, calce o tênis e caminhe 5 minutos.", "Em vez de mudar toda a alimentação, inclua uma fruta no café da manhã.", "Em vez de meditar 30 minutos, faça 5 respirações lentas antes do almoço."]}, {"type": "paragraph", "text": "Quando o passo pequeno estiver firme, aumente aos poucos."}, {"type": "heading", "level": 2, "text": "Técnica 2: encaixe na rotina"}, {"type": "paragraph", "text": "Ligue o hábito novo a algo que você já faz todo dia, usando a frase: \"Depois de [algo que já faço], eu vou [hábito novo]\"."}, {"type": "list", "items": ["Depois de escovar os dentes de manhã, vou beber um copo de água.", "Depois do almoço, vou caminhar 10 minutos.", "Depois de sentar para ver o jornal, vou levantar e sentar da cadeira 5 vezes."]}, {"type": "heading", "level": 2, "text": "Técnica 3: facilite o caminho"}, {"type": "paragraph", "text": "O ambiente decide muito por nós. Deixe a fruteira à vista, a garrafa de água ao lado da poltrona e o tênis separado na noite anterior. E deixe mais difícil o que atrapalha: doces guardados em lugar alto, controle da TV longe do sofá."}, {"type": "heading", "level": 2, "text": "Técnica 4: registre e comemore"}, {"type": "paragraph", "text": "Marque um X no calendário a cada dia cumprido. Ver a sequência crescer motiva a continuar. Conte o progresso para alguém de confiança e comemore depois de um mês."}, {"type": "blockquote", "text": "Se falhar um dia, não desista. A regra é simples: nunca falhar dois dias seguidos."}, {"type": "heading", "level": 2, "text": "Junte-se a alguém"}, {"type": "paragraph", "text": "Hábitos feitos em companhia duram mais. Combine caminhadas com um vizinho, entre num grupo de dança ou hidroginástica, ou peça a um familiar para lembrar e comemorar com você."}, {"type": "paragraph", "text": "", "html": "<p>O passo a passo completo, com painel semanal para imprimir, está no <a href=\"/biblioteca/guia-habitos-saudaveis\">Guia Hábitos Saudáveis</a>, gratuito. Para escolher por onde começar, faça o <a href=\"/ferramentas/quiz-saude-bem\">quiz Saúde & Bem</a>.</p>"}, {"type": "faq", "items": [{"question": "É verdade que um hábito se forma em 21 dias?", "answer": "Esse número é um mito popular. Estudos mostram que, em média, leva cerca de 2 meses, com variação de semanas a meses conforme a pessoa e o hábito."}, {"question": "Posso mudar vários hábitos ao mesmo tempo?", "answer": "Pode, mas as chances de sucesso são maiores com um de cada vez. Quando o primeiro estiver firme, use-o como gatilho para o próximo."}, {"question": "O que fazer quando a motivação acaba?", "answer": "Diminua o tamanho do hábito em vez de parar. Um hábito pequeno cabe até nos dias sem vontade."}]}, {"type": "paragraph", "text": "", "html": "<p>Conteúdo informativo da Equipe Saúde & Bem, baseado em Lally e colaboradores (European Journal of Social Psychology, 2010).</p>"}]$c$::jsonb,
  updated_at = now()
where slug = 'como-criar-habitos-saudaveis';

update public.articles set
  title = 'Cansaço depois dos 50: como ter mais energia no dia a dia',
  excerpt = 'As causas mais comuns do cansaço, os hábitos que devolvem a disposição e os sinais de que é hora de investigar com o médico.',
  read_time = '5 min',
  seo_title = 'Cansaço depois dos 50: como ter mais energia no dia a dia',
  seo_description = 'Cansaço depois dos 50: causas comuns, hábitos que aumentam a energia (sono, luz, proteína, água e movimento) e quando fazer exames.',
  content = $c$[{"type": "image", "url": "https://images.unsplash.com/photo-1731338493464-db479f155a3a?auto=format&fit=crop&w=1600&q=80", "alt": "Foto ilustrativa: Cansaço depois dos 50: como ter mais energia no dia a dia (Unsplash)"}, {"type": "paragraph", "text": "Sentir-se cansado o tempo todo não precisa ser aceito como \"coisa da idade\". Na maioria das vezes, o cansaço tem causas que podem ser corrigidas, seja nos hábitos, seja com tratamento médico."}, {"type": "heading", "level": 2, "text": "Primeiro: cansaço também pode ser sinal de doença"}, {"type": "paragraph", "text": "Anemia, alterações da tireoide, diabetes, depressão, apneia do sono, falta de vitamina B12 e efeitos de remédios são causas comuns e tratáveis. Procure o médico se o cansaço:"}, {"type": "list", "items": ["Surgiu sem motivo e está piorando.", "Dura mais de 2 a 3 semanas mesmo com descanso.", "Vem com perda de peso, falta de ar, palidez, muita sede ou tristeza persistente.", "Começou depois de um remédio novo."]}, {"type": "paragraph", "text": "Exames simples, como hemograma, glicemia, função da tireoide e vitamina B12, costumam esclarecer boa parte dos casos."}, {"type": "heading", "level": 2, "text": "Os hábitos que mais devolvem a energia"}, {"type": "heading", "level": 3, "text": "Sono de qualidade"}, {"type": "paragraph", "text": "É a causa mais comum de cansaço. Horário fixo para acordar, luz da manhã e menos cafeína à tarde fazem grande diferença."}, {"type": "heading", "level": 3, "text": "Luz natural pela manhã"}, {"type": "paragraph", "text": "Abrir as janelas e passar alguns minutos ao ar livre logo cedo deixa o corpo alerta durante o dia e com sono na hora certa à noite."}, {"type": "heading", "level": 3, "text": "Proteína em todas as refeições"}, {"type": "paragraph", "text": "Com a idade, perdemos músculo com mais facilidade, e a fraqueza muscular é sentida como cansaço. Ovo, iogurte, queijo branco, feijão, frango, peixe ou carne no café, no almoço e no jantar ajudam a preservar a força."}, {"type": "heading", "level": 3, "text": "Água ao longo do dia"}, {"type": "paragraph", "text": "A sede diminui com a idade e a desidratação leve causa cansaço e dor de cabeça. Beba mesmo sem vontade."}, {"type": "heading", "level": 3, "text": "Movimento"}, {"type": "paragraph", "text": "Parece contraditório, mas quem se mexe mais tem mais energia. Comece com 10 minutos de caminhada depois de uma refeição e aumente aos poucos."}, {"type": "heading", "level": 3, "text": "Menos açúcar e refeições pesadas"}, {"type": "paragraph", "text": "Doces e refrigerantes dão um pico rápido de energia, seguido de queda. Refeições muito grandes causam a moleza depois do almoço."}, {"type": "heading", "level": 3, "text": "Pausas e convívio"}, {"type": "paragraph", "text": "Preocupação constante e solidão também cansam. Pausas curtas ao longo do dia e conversar com alguém todos os dias ajudam a energia mental."}, {"type": "paragraph", "text": "", "html": "<p>Mais detalhes em <a href=\"/blog/habitos-matinais-saudaveis\">rotina da manhã para ter mais disposição</a> e <a href=\"/blog/hidratacao-inteligente\">hidratação depois dos 60</a>.</p>"}, {"type": "blockquote", "text": "Evite suplementos e energéticos \"para cansaço\" sem orientação. Eles podem mascarar uma doença que precisa ser tratada e interagir com remédios."}, {"type": "faq", "items": [{"question": "Cansaço é normal na terceira idade?", "answer": "Um pouco menos de fôlego pode acontecer, mas cansaço constante que atrapalha o dia não é normal e merece investigação."}, {"question": "Café ajuda a ter energia?", "answer": "Com moderação e até o almoço, pode ajudar. Em excesso ou à tarde, atrapalha o sono e acaba piorando o cansaço do dia seguinte."}, {"question": "Vitamina B12 dá energia?", "answer": "Ela só ajuda quem tem falta, o que é mais comum em pessoas mais velhas e em quem usa alguns remédios por muito tempo. O médico confirma com exame."}]}, {"type": "paragraph", "text": "", "html": "<p>Conteúdo informativo da Equipe Saúde & Bem. Plano de 14 dias para mais disposição no <a href=\"/biblioteca/guia-energia-natural\">Guia Energia Natural</a>, gratuito.</p>"}]$c$::jsonb,
  updated_at = now()
where slug = 'como-aumentar-energia-naturalmente';

update public.articles set
  title = 'Memória e foco depois dos 50: hábitos que mantêm a mente afiada',
  excerpt = 'O que é esquecimento normal, o que merece atenção e os hábitos com evidência para manter a memória e a concentração.',
  read_time = '5 min',
  seo_title = 'Memória e foco depois dos 50: hábitos que mantêm a mente afiada',
  seo_description = 'Memória e concentração depois dos 50: esquecimento normal ou não, hábitos que protegem o cérebro, estratégias práticas e quando procurar o médico.',
  content = $c$[{"type": "image", "url": "https://images.unsplash.com/photo-1758612898691-afe3e1d08a0a?auto=format&fit=crop&w=1600&q=80", "alt": "Foto ilustrativa: Memória e foco depois dos 50: hábitos que mantêm a mente afiada (Unsplash)"}, {"type": "paragraph", "text": "Esquecer onde deixou os óculos ou o nome de um conhecido acontece com todo mundo, e um pouco mais com o passar dos anos. A boa notícia é que o cérebro continua capaz de aprender em qualquer idade, e vários hábitos ajudam a manter a memória e o foco."}, {"type": "heading", "level": 2, "text": "Esquecimento normal ou sinal de alerta?"}, {"type": "paragraph", "text": "É comum, com a idade, demorar mais para lembrar um nome que depois volta à memória, ou perder objetos de vez em quando. Merecem avaliação médica:"}, {"type": "list", "items": ["Esquecer acontecimentos recentes inteiros e repetir as mesmas perguntas.", "Perder-se em lugares conhecidos.", "Dificuldade crescente com tarefas antes simples, como pagar contas ou seguir uma receita.", "Mudanças de comportamento ou de personalidade notadas pela família."]}, {"type": "paragraph", "text": "Várias causas de esquecimento são tratáveis, como falta de vitamina B12, alterações da tireoide, depressão, sono ruim e efeitos de remédios."}, {"type": "heading", "level": 2, "text": "Hábitos que protegem o cérebro"}, {"type": "heading", "level": 3, "text": "Movimento"}, {"type": "paragraph", "text": "A atividade física aumenta o fluxo de sangue para o cérebro e está associada a menor risco de declínio da memória."}, {"type": "heading", "level": 3, "text": "Pressão, glicose e colesterol controlados"}, {"type": "paragraph", "text": "O que faz bem ao coração faz bem ao cérebro. Manter essas medidas sob controle protege os vasos que irrigam o cérebro."}, {"type": "heading", "level": 3, "text": "Sono"}, {"type": "paragraph", "text": "É durante o sono que a memória é consolidada. Ronco com pausas na respiração e sono muito ruim podem atrapalhar a concentração."}, {"type": "heading", "level": 3, "text": "Audição e visão em dia"}, {"type": "paragraph", "text": "A perda de audição sem tratamento está entre os fatores de risco para o declínio cognitivo. Faça avaliações e use aparelhos ou óculos quando indicados."}, {"type": "heading", "level": 3, "text": "Mente ativa e convívio"}, {"type": "paragraph", "text": "Aprender coisas novas, ler, fazer trabalhos manuais, jogar e, principalmente, conversar e conviver mantêm o cérebro estimulado."}, {"type": "heading", "level": 2, "text": "Estratégias práticas para o dia a dia"}, {"type": "list", "items": ["Tenha um lugar fixo para chaves, óculos e documentos.", "Use agenda, calendário na parede ou lembretes no celular.", "Organize os remédios numa caixa por dia da semana.", "Faça uma coisa de cada vez: dividir a atenção atrapalha a memória.", "Repita em voz alta o nome de quem acabou de conhecer."]}, {"type": "blockquote", "text": "Desconfie de suplementos que prometem \"turbinar a memória\". Nenhum deles tem eficácia comprovada para prevenir a perda de memória."}, {"type": "paragraph", "text": "", "html": "<p>Para cuidar dos hábitos que mais protegem o cérebro, veja <a href=\"/blog/exercicios-para-iniciantes\">exercícios para iniciantes</a> e <a href=\"/blog/como-melhorar-qualidade-do-sono\">qualidade do sono depois dos 50</a>.</p>"}, {"type": "faq", "items": [{"question": "Palavras cruzadas previnem a perda de memória?", "answer": "Atividades que desafiam a mente ajudam, principalmente as que envolvem aprender algo novo e conviver com outras pessoas. Elas funcionam melhor junto com atividade física e controle da saúde."}, {"question": "Ansiedade atrapalha a memória?", "answer": "Sim. Ansiedade, estresse e depressão dificultam a concentração e podem parecer problemas de memória. Tratar essas condições costuma melhorar o foco."}, {"question": "Quando devo procurar o médico?", "answer": "Quando os esquecimentos atrapalham o dia a dia, estão piorando ou são percebidos pela família. Quanto antes a avaliação, melhores as opções."}]}, {"type": "paragraph", "text": "", "html": "<p>Conteúdo informativo da Equipe Saúde & Bem, com base no relatório da Comissão Lancet sobre prevenção de demência (2024).</p>"}]$c$::jsonb,
  updated_at = now()
where slug = 'como-melhorar-produtividade';

update public.articles set
  title = 'Saúde mental depois dos 50: rotina, convívio e sinais de depressão',
  excerpt = 'Como a rotina e o convívio protegem a saúde mental, a diferença entre tristeza e depressão e onde buscar ajuda.',
  read_time = '5 min',
  seo_title = 'Saúde mental depois dos 50: rotina, convívio e sinais de depressão',
  seo_description = 'Saúde mental depois dos 50: rotina que protege, combate à solidão, diferença entre tristeza e depressão, sinais de alerta e onde buscar ajuda no SUS.',
  content = $c$[{"type": "image", "url": "https://images.unsplash.com/photo-1764173039543-f9f197744e1b?auto=format&fit=crop&w=1600&q=80", "alt": "Foto ilustrativa: Saúde mental depois dos 50: rotina, convívio e sinais de depressão (Unsplash)"}, {"type": "paragraph", "text": "Mudanças comuns depois dos 50, como aposentadoria, filhos que saem de casa, perdas e problemas de saúde, mexem com as emoções. Sentir tristeza nesses momentos é natural. O que protege a saúde mental é ter uma rotina com sentido, pessoas por perto e atenção aos sinais de que algo não vai bem."}, {"type": "heading", "level": 2, "text": "Uma rotina que protege"}, {"type": "list", "items": ["Horários regulares para acordar, comer e dormir dão estrutura ao dia.", "Atividade física regular melhora o humor e o sono.", "Ter algo para fazer de manhã e algo para esperar na semana dá sentido aos dias.", "Tempo ao ar livre e luz natural ajudam o humor."]}, {"type": "heading", "level": 2, "text": "Solidão: um risco para a saúde"}, {"type": "paragraph", "text": "A solidão e o isolamento social estão associados a mais depressão, declínio da memória e doenças do coração. Algumas formas de manter o convívio:"}, {"type": "list", "items": ["Ligar ou visitar alguém todos os dias.", "Participar de grupos de convivência, igrejas, associações ou clubes.", "Fazer trabalho voluntário.", "Aprender algo em grupo: dança, coral, artesanato, informática.", "Usar videochamadas para falar com quem mora longe."]}, {"type": "heading", "level": 2, "text": "Tristeza ou depressão?"}, {"type": "paragraph", "text": "A tristeza passa e não impede a pessoa de viver. A depressão é uma doença, com tratamento, e pode aparecer de forma diferente em pessoas mais velhas, às vezes mais como cansaço, dores e falta de interesse do que como choro. Fique atento se, por mais de 2 semanas, houver:"}, {"type": "list", "items": ["Desânimo e perda de interesse por coisas que antes davam prazer.", "Alterações do sono ou do apetite.", "Cansaço constante e sensação de inutilidade.", "Isolamento, irritação ou dificuldade de concentração.", "Pensamentos de morte."]}, {"type": "blockquote", "text": "Se você ou alguém próximo tiver pensamentos de tirar a própria vida, ligue para o CVV no 188 (gratuito, 24 horas) ou procure um pronto-atendimento. Falar sobre isso salva vidas."}, {"type": "heading", "level": 2, "text": "Onde buscar ajuda"}, {"type": "paragraph", "text": "No SUS, a unidade básica de saúde é a porta de entrada: o médico pode avaliar, tratar e encaminhar para psicólogo ou para o CAPS quando necessário. Depressão tem tratamento eficaz, com psicoterapia e, quando indicado, medicamentos. Não é fraqueza nem \"coisa da idade\"."}, {"type": "paragraph", "text": "", "html": "<p>Técnicas para o dia a dia em <a href=\"/blog/controle-ansiedade\">ansiedade depois dos 50</a> e <a href=\"/blog/como-reduzir-estresse-naturalmente\">como reduzir o estresse</a>.</p>"}, {"type": "faq", "items": [{"question": "Depressão é normal na velhice?", "answer": "Não. Ela é mais comum em algumas situações, como doenças e perdas, mas não faz parte do envelhecimento normal e deve ser tratada."}, {"question": "Como ajudar um familiar que está se isolando?", "answer": "Mantenha contato frequente, convide para atividades sem pressionar e incentive a consulta médica. Ouvir sem julgar já ajuda muito."}, {"question": "Atividade física ajuda na depressão?", "answer": "Sim, ajuda no tratamento e na prevenção, junto com o acompanhamento profissional."}]}, {"type": "paragraph", "text": "", "html": "<p>Conteúdo informativo da Equipe Saúde & Bem. Não substitui avaliação profissional. Para montar uma rotina com sentido, baixe o <a href=\"/biblioteca/guia-habitos-saudaveis\">Guia Hábitos Saudáveis</a>.</p>"}]$c$::jsonb,
  updated_at = now()
where slug = 'saude-mental-rotina';

update public.articles set
  title = 'Como organizar uma semana saudável depois dos 50',
  excerpt = 'Um modelo de semana equilibrada, com movimento, alimentação, descanso, convívio e cuidados de saúde, para adaptar à sua vida.',
  read_time = '4 min',
  seo_title = 'Como organizar uma semana saudável depois dos 50',
  seo_description = 'Como organizar uma semana saudável depois dos 50: modelo de rotina com atividade física, refeições, sono, convívio, remédios e consultas.',
  content = $c$[{"type": "image", "url": "https://images.unsplash.com/photo-1632772998001-cc9bf6f7c852?auto=format&fit=crop&w=1600&q=80", "alt": "Foto ilustrativa: Como organizar uma semana saudável depois dos 50 (Unsplash)"}, {"type": "paragraph", "text": "Com a aposentadoria ou com os filhos já criados, muitas pessoas descobrem que a semana perdeu a estrutura de antes. Organizar os dias não é encher a agenda: é garantir espaço para o que mantém a saúde, sem esquecer o descanso e o prazer."}, {"type": "heading", "level": 2, "text": "Os blocos de uma semana equilibrada"}, {"type": "list", "items": ["Movimento: caminhada na maioria dos dias e força em 2 a 3 dias.", "Refeições em horários regulares, com comida feita em casa sempre que possível.", "Sono: horário fixo para acordar todos os dias.", "Convívio: pelo menos um encontro ou atividade em grupo por semana.", "Mente ativa: leitura, um curso, um hobby.", "Cuidados de saúde: remédios, consultas e exames organizados.", "Descanso e lazer, sem culpa."]}, {"type": "heading", "level": 2, "text": "Um modelo para adaptar"}, {"type": "paragraph", "text": "Use como ponto de partida e troque o que não combinar com a sua vida:"}, {"type": "list", "items": ["Segunda: caminhada de manhã, feira ou mercado, preparar refeições da semana.", "Terça: exercícios de força em casa, tarde livre para hobby.", "Quarta: caminhada, atividade em grupo ou voluntariado.", "Quinta: exercícios de força, conferir remédios e agenda de consultas.", "Sexta: caminhada, ligar para amigos e familiares, combinar o fim de semana.", "Sábado: passeio ao ar livre, encontro com a família ou amigos.", "Domingo: descanso, alongamento leve e planejamento da semana seguinte."]}, {"type": "heading", "level": 2, "text": "Remédios e consultas sem esquecimento"}, {"type": "list", "items": ["Caixa organizadora de remédios por dia e horário.", "Lista atualizada de todos os remédios, com doses, para levar às consultas.", "Calendário na parede ou no celular com consultas, exames e vacinas.", "Um dia fixo da semana para conferir se falta algum remédio."]}, {"type": "blockquote", "text": "Leve a lista de remédios a todas as consultas, inclusive vitaminas, chás e remédios naturais. Assim o médico evita interações perigosas."}, {"type": "heading", "level": 2, "text": "Dicas para a rotina durar"}, {"type": "list", "items": ["Comece com poucos compromissos e acrescente aos poucos.", "Deixe folgas: imprevistos acontecem.", "Revise a semana no domingo: o que funcionou, o que mudar.", "Se um dia não sair como planejado, recomece no dia seguinte."]}, {"type": "paragraph", "text": "", "html": "<p>Para transformar cada item da semana em hábito, veja <a href=\"/blog/como-criar-habitos-saudaveis\">como criar hábitos saudáveis que duram</a> e use o painel do <a href=\"/biblioteca/guia-habitos-saudaveis\">Guia Hábitos Saudáveis</a>.</p>"}, {"type": "faq", "items": [{"question": "Preciso me exercitar todos os dias?", "answer": "A caminhada pode ser feita na maioria dos dias. Os exercícios de força funcionam melhor em 2 a 3 dias não seguidos. Descansar também faz parte."}, {"question": "E se eu não gostar de rotinas rígidas?", "answer": "A ideia não é ter horário para tudo, e sim garantir que os blocos importantes aconteçam ao longo da semana, do jeito que for mais confortável."}, {"question": "Como incluir a família na rotina?", "answer": "Combine atividades que façam bem a todos, como caminhadas, refeições em conjunto e passeios no fim de semana."}]}, {"type": "paragraph", "text": "", "html": "<p>Conteúdo informativo da Equipe Saúde & Bem, baseado nas diretrizes de atividade física da Organização Mundial da Saúde e no Guia Alimentar para a População Brasileira.</p>"}]$c$::jsonb,
  updated_at = now()
where slug = 'como-criar-rotina-sustentavel';
